(function() {
  const $ = (sel) => document.querySelector(sel);
  const $$ = (sel) => document.querySelectorAll(sel);

  // 1. Complexity Slider (Problem Statement)
  const seqSlider = $('#seq-length-slider');
  const rnnBar = $('.rnn-bar');
  const transBar = $('.trans-bar');

  function updateComplexity() {
    const n = parseInt(seqSlider.value);
    // RNN grows linearly, Transformer stays constant (O(1) path length concept)
    const rnnHeight = Math.min(100, n);
    rnnBar.style.height = rnnHeight + '%';
    transBar.style.height = '20%'; // Constant baseline
  }
  if(seqSlider) seqSlider.addEventListener('input', updateComplexity);
  updateComplexity();

  // 2. Architecture Mask Toggle
  const maskBtn = $('#toggle-mask');
  const maskedLayers = $$('.sublayer.masked');
  if(maskBtn) {
    maskBtn.addEventListener('click', () => {
      maskedLayers.forEach(el => {
        const isMasked = el.style.fill === 'rgb(255, 245, 245)' || el.getAttribute('fill') === '#fff5f5';
        if(isMasked) {
          el.style.fill = '#fff';
          el.style.opacity = '1';
        } else {
          el.style.fill = '#fff5f5';
          el.style.opacity = '0.6';
        }
      });
    });
  }

  // 3. Attention Mechanism Lab (Canvas)
  const attnCanvas = $('#attention-canvas');
  const dkSlider = $('#dk-slider');
  const scaleCheck = $('#scale-check');
  const dkVal = $('#dk-val');
  const attnOutput = $('#attn-output-display');
  const attnReset = $('#attn-reset');

  if(attnCanvas && attnCanvas.getContext) {
    const ctx = attnCanvas.getContext('2d');
    let q = [1, 0, 2];
    let k = [[1, 0, 1], [0, 1, -1], [-1, 1, 0]];
    let v = [1, 2, -1];

    function drawAttention() {
      const dk = parseInt(dkSlider.value);
      dkVal.textContent = dk;
      const useScale = scaleCheck.checked;
      const scale = useScale ? 1 / Math.sqrt(dk) : 1;

      // Compute Scores (Q dot K^T)
      // Simplified for demo: Q is 1x3, K is 3x3. Result 1x3.
      const scores = k.map((row, i) => {
        return (q[0]*row[0] + q[1]*row[1] + q[2]*row[2]) * scale;
      });

      // Softmax
      const maxScore = Math.max(...scores);
      const expScores = scores.map(s => Math.exp(s - maxScore));
      const sumExp = expScores.reduce((a, b) => a + b, 0);
      const weights = expScores.map(s => s / sumExp);

      // Output (Weights dot V)
      const output = weights.reduce((acc, w, i) => acc + w * v[i], 0);
      attnOutput.textContent = `Output: ${output.toFixed(4)}`;

      // Draw Bars
      ctx.clearRect(0, 0, attnCanvas.width, attnCanvas.height);
      const barWidth = 60;
      const gap = 40;
      const startX = 50;
      const maxY = 150;

      weights.forEach((w, i) => {
        const h = w * maxY;
        const x = startX + i * (barWidth + gap);
        const y = 180 - h;

        ctx.fillStyle = '#2C5282';
        ctx.fillRect(x, y, barWidth, h);

        ctx.fillStyle = '#000';
        ctx.font = '12px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(`w${i}: ${w.toFixed(2)}`, x + barWidth/2, 195);
        ctx.fillText(`s${i}: ${scores[i].toFixed(1)}`, x + barWidth/2, y - 5);
      });
    }

    dkSlider.addEventListener('input', drawAttention);
    scaleCheck.addEventListener('change', drawAttention);
    if(attnReset) attnReset.addEventListener('click', () => {
      dkSlider.value = 64;
      scaleCheck.checked = true;
      drawAttention();
    });
    drawAttention();
  }

  // 4. Positional Encoding Canvas
  const peCanvas = $('#pe-canvas');
  const pePosSlider = $('#pe-pos');
  const pePosVal = $('#pe-pos-val');

  if(peCanvas && peCanvas.getContext) {
    const ctx = peCanvas.getContext('2d');
    const d_model = 64;

    function drawPE() {
      const pos = parseInt(pePosSlider.value);
      pePosVal.textContent = pos;

      ctx.clearRect(0, 0, peCanvas.width, peCanvas.height);
      ctx.fillStyle = '#f0f4f8';
      ctx.fillRect(0, 0, peCanvas.width, peCanvas.height);

      // Draw heatmap for current position across dimensions
      const cellW = peCanvas.width / d_model;

      for(let i=0; i<d_model; i++) {
        const val = (i % 2 === 0) 
          ? Math.sin(pos / Math.pow(10000, (2*i)/d_model))
          : Math.cos(pos / Math.pow(10000, (2*(i-1))/d_model));

        // Map -1..1 to color
        const intensity = Math.floor(((val + 1) / 2) * 255);
        ctx.fillStyle = `rgb(${255-intensity}, ${intensity}, ${100})`;
        ctx.fillRect(i * cellW, 0, cellW + 1, peCanvas.height);
      }

      // Draw marker line
      ctx.strokeStyle = '#DD6B20';
      ctx.lineWidth = 2;
      ctx.beginPath();
      const markerX = (pos / 100) * peCanvas.width;
      ctx.moveTo(markerX, 0);
      ctx.lineTo(markerX, peCanvas.height);
      ctx.stroke();
    }

    pePosSlider.addEventListener('input', drawPE);
    drawPE();
  }

  // 5. Complexity Analysis Bars
  const compN = $('#comp-n');
  const compD = $('#comp-d');
  const compBars = $('#complexity-bars');

  function updateCompBars() {
    const n = parseInt(compN.value);
    const d = parseInt(compD.value);

    // Theoretical Ops (ignoring constants)
    const selfAttn = n * n * d;
    const recurrent = n * d * d;
    const conv = 3 * n * d * d; // Approx

    const maxVal = Math.max(selfAttn, recurrent, conv);

    compBars.innerHTML = `
      <div class="bar-group" style="flex-direction:column; height:150px;">
        <div class="bar" style="height:${(selfAttn/maxVal)*100}%; background:#2C5282;"></div>
        <span>Self-Attn<br>${selfAttn.toExponential(1)}</span>
      </div>
      <div class="bar-group" style="flex-direction:column; height:150px;">
        <div class="bar" style="height:${(recurrent/maxVal)*100}%; background:#a0aec0;"></div>
        <span>RNN<br>${recurrent.toExponential(1)}</span>
      </div>
      <div class="bar-group" style="flex-direction:column; height:150px;">
        <div class="bar" style="height:${(conv/maxVal)*100}%; background:#ed8936;"></div>
        <span>CNN<br>${conv.toExponential(1)}</span>
      </div>
    `;
  }

  if(compN) compN.addEventListener('input', updateCompBars);
  if(compD) compD.addEventListener('change', updateCompBars);
  updateCompBars();

  // 6. Results Data (Runtime Data Mock based on Paper Tables)
  // Note: In real runtime, this would come from window.paperMindData.tables
  const table2Data = {
    ende: [
      {model: 'Transformer (big)', bleu: 28.4, flops: 2.3e19},
      {model: 'GNMT+RL Ens', bleu: 26.3, flops: 1.8e20},
      {model: 'ConvS2S Ens', bleu: 26.36, flops: 7.7e19}
    ],
    enfr: [
      {model: 'Transformer (big)', bleu: 41.8, flops: 2.3e19},
      {model: 'GNMT+RL Ens', bleu: 41.16, flops: 1.1e21},
      {model: 'ConvS2S Ens', bleu: 41.29, flops: 1.2e21}
    ]
  };

  const taskSelect = $('#task-select');
  const bleuChart = $('#bleu-chart');
  const flopsChart = $('#flops-chart');
  const discrepancyMsg = $('#discrepancy-msg');

  function renderResults() {
    if(!taskSelect) return;
    const task = taskSelect.value;
    const data = table2Data[task];

    // Show discrepancy note for EN-FR
    if(task === 'enfr') {
      discrepancyMsg.style.display = 'block';
    } else {
      discrepancyMsg.style.display = 'none';
    }

    // Render BLEU
    const maxBleu = Math.max(...data.map(d => d.bleu));
    bleuChart.innerHTML = data.map(d => `
      <div class="bar-item" style="height:${(d.bleu/maxBleu)*100}%">
        <div class="value-label">${d.bleu}</div>
        <span>${d.model}</span>
      </div>
    `).join('');

    // Render FLOPs (Log scale for visibility)
    const maxFlops = Math.max(...data.map(d => d.flops));
    flopsChart.innerHTML = data.map(d => `
      <div class="bar-item" style="height:${(d.flops/maxFlops)*100}%; background:#DD6B20">
        <div class="value-label">${d.flops.toExponential(1)}</div>
        <span>${d.model}</span>
      </div>
    `).join('');
  }

  if(taskSelect) taskSelect.addEventListener('change', renderResults);
  renderResults();

  // 7. Ablation Studies
  const ablationSelect = $('#ablation-select');
  const ablationBleu = $('#ablation-bleu');
  const ablationPpl = $('#ablation-ppl');

  // Data from Table 3
  const ablationData = {
    'base': {bleu: 25.8, ppl: 4.92},
    'A_1': {bleu: 24.9, ppl: 5.29}, // Single head
    'C_1': {bleu: 23.7, ppl: 6.11}, // N=2
    'D_1': {bleu: 24.6, ppl: 5.77}  // No dropout
  };

  if(ablationSelect) {
    ablationSelect.addEventListener('change', (e) => {
      const d = ablationData[e.target.value];
      ablationBleu.textContent = d.bleu;
      ablationPpl.textContent = d.ppl;
    });
  }

  // Navigation
  $$('.nav-controls button').forEach(btn => {
    btn.addEventListener('click', () => {
      const targetId = btn.getAttribute('data-scroll');
      const el = document.getElementById(targetId);
      if(el) el.scrollIntoView({behavior: 'smooth'});
    });
  });

  // Source Buttons
  $$('.source-btn').forEach(btn => {
    btn.addEventListener('click', (e) => {
      const sourceId = btn.getAttribute('data-source');
      // In real runtime, this triggers the source viewer
      console.log('Request source:', sourceId);
      alert('请求来源：' + sourceId + '\n(由内核处理桥接)');
    });
  });

})();
